from lib import *
S = SS('v92')
steps = [
    step("单个请求要多花多少时间(本机回环,并发 1,keep-alive,每轮 20000 个请求,3 轮取中位数那一轮)。直连后端:平均 43 µs,p99 96 µs。经过一个 Envoy:平均 124 µs,p99 229 µs。经过两个 Envoy(明文,即客户端和服务端各一个 sidecar):平均 218 µs,p99 378 µs。两个 Envoy 之间用 mTLS:平均 223 µs,p99 381 µs。相对直连多出的平均延迟:一个 Envoy 加 82 µs,两个 Envoy 加 175 µs,mTLS 加 181 µs。D 与 C 只差几微秒,我的解释是握手只在建连时发生,没有单独验证。这是回环上的数字,真实网络的往返会让这点开销占比更小。", t=tl(S(1)), mark=lidx(S(1), 'B 一个 Envoy', 'C 两个 Envoy(明文)'), done=lidx(S(1), 'A 直连'), b=bars([['A 直连 平均 µs', 43, '43'], ['B 一个 Envoy 平均 µs', 124, '124(+82)'], ['C 两个 Envoy 平均 µs', 218, '218(+175)'], ['D 两个 Envoy + mTLS 平均 µs', 223, '223(+181)']], 230, done=[0], cur=[1, 2, 3]), kv=KV([['一个 Envoy', '+82 µs(平均)'], ['两个 Envoy', '+175 µs(平均)'], ['再加 mTLS', '再多约 6 µs'], ['p99', '96 → 229 → 378 µs']], ['两个 Envoy'])),
    step("并发 32、keep-alive 下的吞吐和 CPU(Envoy 只开 1 个工作线程)。直连:92324 请求/秒。一个 Envoy:26419 请求/秒,p50 1178 µs,Envoy CPU 37 µs/请求。两个 Envoy:19297 请求/秒,p50 1600 µs,CPU 85 µs/请求。两个 Envoy + mTLS:18034 请求/秒,p50 1709 µs,CPU 90 µs/请求。压测程序、nginx、Envoy 在同一台机器上,直连的吞吐可能是压测程序自己的上限,不是 nginx 的极限;CPU 一列只算 Envoy 进程。", t=tl(S(2)), mark=lidx(S(2), 'B 一个 Envoy', 'C 两个 Envoy(明文)'), done=lidx(S(2), 'A 直连', 'D 两个 Envoy(mTLS)'), b=bars([['A 直连 请求/秒', 92324, '92324'], ['B 一个 Envoy 请求/秒', 26419, '26419'], ['C 两个 Envoy 请求/秒', 19297, '19297'], ['D 两个 Envoy + mTLS 请求/秒', 18034, '18034']], 92324, done=[0], cur=[1, 2, 3]), kv=KV([['一个 Envoy CPU', '37 µs/请求'], ['两个 Envoy CPU', '85 µs/请求'], ['mTLS 两个 Envoy CPU', '90 µs/请求'], ['注意', '直连可能受压测程序限制']], ['两个 Envoy CPU'])),
    step("每次请求新建连接(并发 1,每轮 3000 个请求,轮间隔 5 s)。直连:平均 324 µs。一个 Envoy:370 µs,多 46 µs。两个 Envoy:497 µs,多 172 µs。两个 Envoy + mTLS:466 µs,多 141 µs,反而比明文的两个 Envoy 快,这是噪声:3 轮平均延迟的范围分别是 487~524 µs 和 384~515 µs,互相重叠。这一节的差别比 keep-alive 时更不稳定,不能读出 mTLS 比明文快。", t=tl(S(3)), mark=lidx(S(3), 'C 两个 Envoy(明文)', 'D 两个 Envoy(mTLS)'), done=lidx(S(3), 'A 直连', 'B 一个 Envoy'), b=bars([['A 直连 平均 µs', 324, '324'], ['B 一个 Envoy 平均 µs', 370, '370(+46)'], ['C 两个 Envoy 平均 µs', 497, '497(+172)'], ['D 两个 Envoy + mTLS 平均 µs', 466, '466(+141,噪声)']], 500, done=[0], cur=[1, 2, 3]), kv=KV([['新建连接直连', '324 µs'], ['两个 Envoy', '+172 µs'], ['mTLS 比明文快?', '3 轮范围重叠,是噪声'], ['对比 keep-alive', '直连基线高 7 倍多']], ['mTLS 比明文快?'])),
    step("100 KB 的响应(并发 1,keep-alive,每轮 5000 个请求)。直连:平均 108 µs,约 945 MB/s。一个 Envoy:220 µs,约 464 MB/s。两个 Envoy:343 µs,约 298 MB/s。两个 Envoy + mTLS:385 µs,约 266 MB/s。响应变大之后,两个 Envoy 比直连多 235 µs,mTLS 多 277 µs。我的解释是每多一跳就多拷贝一次响应体,mTLS 再多一次加解密,没有单独验证。", t=tl(S(4)), mark=lidx(S(4), 'C 两个 Envoy(明文)', 'D 两个 Envoy(mTLS)'), done=lidx(S(4), 'A 直连', 'B 一个 Envoy'), b=bars([['A 直连 平均 µs', 108, '108'], ['B 一个 Envoy 平均 µs', 220, '220'], ['C 两个 Envoy 平均 µs', 343, '343(+235)'], ['D 两个 Envoy + mTLS 平均 µs', 385, '385(+277)']], 390, done=[0], cur=[1, 2, 3]), kv=KV([['直连', '约 945 MB/s'], ['两个 Envoy', '约 298 MB/s'], ['两个 Envoy + mTLS', '约 266 MB/s'], ['响应变大', '额外延迟 175 → 235 µs']], ['两个 Envoy'])),
    step("内存。Envoy 常驻内存和配置里的集群数的关系(静态配置,每个集群一个端点、一条路由)。1 个集群:启动到可连接 0.21 s,空闲 RSS 40 MB。100 个:0.20 s,43 MB。1000 个:0.41 s,78 MB。5000 个:1.62 s,262 MB。按 1 个和 5000 个之差估算每个集群约 44 KB。压测之后各 Envoy 的 RSS 都在 40 到 43 MB。1000 个集群的 RSS 在另一次运行里是 119 MB(这次 78 MB),内存数字在 macOS 上波动大。真实网格里 Envoy 还要保存端点和统计项,每个 sidecar 都收到全网格的配置,所以每个 Pod 都要为所有服务付这份内存。", t=tl(S(5)), mark=lidx(S(5), '压测之后各 Envoy 的 RSS'), done=lidx(S(5), '按 1 个集群和 5000 个集群之间的差估算'), b=bars([['1 个集群 RSS MB', 40, '40'], ['100 个集群 RSS MB', 43, '43'], ['1000 个集群 RSS MB', 78, '78(另一次 119)'], ['5000 个集群 RSS MB', 262, '262']], 262, done=[0, 1], cur=[2, 3]), kv=KV([['空闲基线', '约 40 MB'], ['每个集群', '约 44 KB(静态配置)'], ['5000 个集群', '262 MB,启动 1.62 s'], ['含义', '每个 sidecar 都要为全网格配置付内存']], ['每个集群'])),
]
